const question = $('Fetch Context').first().json.question;
const rawHistory = $('Fetch Context').first().json.history;
const history = Array.isArray(rawHistory) ? rawHistory.filter(h => h && (h.role === 'user' || h.role === 'assistant') && typeof h.content === 'string').slice(-5) : [];

// Récupère tous les incidents
let incidents = [];
try {
  incidents = $('Get Incidents').all().map(i => i.json);
} catch(e) { incidents = []; }

// Résumé compact pour Claude
const summary = incidents.slice(0, 20).map(i => ({
  ref: i.incidentRef,
  project: i.projectName,
  source: i.source,
  status: i.status,
  severity: i.severity,
  title: i.title,
  created: i.createdAt
}));

// Formater l'historique
const historyText = history.length > 0
  ? '\nHISTORIQUE DE LA CONVERSATION :\n' + history.slice(-5).map(h => 
      `${h.role === 'user' ? 'Utilisateur' : 'Assistant'}: ${h.content.substring(0, 200)}`
    ).join('\n') + '\n'
  : '';

const prompt = `Tu es un assistant DevSecOps expert intégré dans la plateforme Vermeg.
Tu as accès aux données réelles de la plateforme.
${historyText}
DONNÉES DE LA PLATEFORME :
${JSON.stringify(summary, null, 2).substring(0, 4000)}

INSTRUCTIONS :
- Vérifier les projets disponibles avant chaque réponse
- Réponds toujours en français
- Si on te demande un projet spécifique, filtre les données correspondantes
- Sois précis, utilise les données réelles
- Réponse claire et correcte
- Si tu ne trouves pas de données → dis-le clairement
- Pour les questions de suivi, utilise l'historique ci-dessus

QUESTION : ${question}`;

return [{ json: { prompt, question, history } }];

const body = $input.first()?.json?.body;
if (!body || typeof body.question !== 'string' || !body.question.trim()) {
  throw new Error('CHAT_INVALID_REQUEST');
}
const history = Array.isArray(body.history)
  ? body.history.filter(h => h && (h.role === 'user' || h.role === 'assistant') && typeof h.content === 'string').slice(-5)
  : [];
return [{ json: {
  question: body.question.trim(),
  ...(typeof body.projectId === 'string' && body.projectId.trim() ? { projectId: body.projectId.trim() } : {}),
  history,
} }];

const response = $input.first()?.json;
if (!response || !Array.isArray(response.content) || response.content.length === 0) {
  throw new Error('CHAT_INVALID_PROVIDER_RESPONSE');
}
const textBlocks = response.content.filter(block => block && block.type === 'text');
if (textBlocks.length === 0 || textBlocks.some(block => typeof block.text !== 'string' || !block.text.trim())) {
  throw new Error('CHAT_INVALID_PROVIDER_RESPONSE');
}
const answer = textBlocks.map(block => block.text.trim()).join('\n');
return [{ json: { ok: true, answer } }];

const prompt = $input.first().json.prompt;

const body = JSON.stringify({
  model: "claude-opus-4-5",
  max_tokens: 1024,
  messages: [
    {
      role: "user",
      content: prompt
    }
  ]
});

return [{ json: { claudeBody: body } }];

return [{ json: {
  ok: false,
  answer: null,
  error: { code: 'CHAT_WORKFLOW_ERROR', message: 'Unable to process the chat request.' },
} }];
